import React from 'react';

/**
 * VariablesPanel - Shows all current variables and their values
 */
const VariablesPanel = ({ variables, isDarkMode }) => {
  const variableNames = Object.keys(variables);
  
  if (variableNames.length === 0) {
    return (
      <div style={{
        padding: '1rem',
        backgroundColor: isDarkMode ? '#2d2d44' : '#ffffff',
        borderRadius: '8px',
        border: '2px solid var(--border-color)',
        marginTop: '1rem'
      }}>
        <h3 style={{
          marginBottom: '0.75rem',
          color: 'var(--text-primary)',
          fontSize: '1.1rem'
        }}>
          🔍 Variables
        </h3>
        <p style={{ 
          color: 'var(--text-secondary)', 
          fontStyle: 'italic',
          textAlign: 'center',
          padding: '2rem'
        }}>
          No variables yet. Use `input` to create variables!
        </p>
      </div>
    );
  }
  
  return (
    <div style={{
      padding: '1rem',
      backgroundColor: isDarkMode ? '#2d2d44' : '#ffffff',
      borderRadius: '8px',
      border: '2px solid var(--border-color)',
      marginTop: '1rem'
    }}>
      <h3 style={{
        marginBottom: '0.75rem',
        color: 'var(--text-primary)',
        fontSize: '1.1rem'
      }}>
        🔍 Variables
      </h3>
      
      <div style={{
        display: 'grid',
        gap: '0.5rem'
      }}>
        {variableNames.map((varName) => (
          <div
            key={varName}
            style={{
              padding: '0.75rem 1rem',
              backgroundColor: isDarkMode ? '#3d3d5c' : '#f9f9f9',
              borderRadius: '6px',
              border: `2px solid ${isDarkMode ? '#4a4a6a' : '#e0e0e0'}`,
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}
          >
            <span style={{
              fontWeight: '600',
              color: isDarkMode ? '#9CDCFE' : '#001080',
              fontSize: '0.95rem'
            }}>
              {varName}
            </span>
            <span style={{
              fontFamily: "'Courier New', monospace",
              color: isDarkMode ? '#CE9178' : '#A31515',
              fontSize: '0.9rem',
              backgroundColor: isDarkMode ? '#1a1a2e' : '#f0f0f0',
              padding: '0.25rem 0.75rem',
              borderRadius: '4px'
            }}>
              "{variables[varName] || ''}"
            </span>
          </div>
        ))}
      </div>
      
      <p style={{
        marginTop: '0.75rem',
        fontSize: '0.85rem',
        color: 'var(--text-secondary)',
        fontStyle: 'italic'
      }}>
        💡 Variables are created when you use the `input` statement
      </p>
    </div>
  );
};

export default VariablesPanel;
